import{bV as a,aL as s,u as n,G as r}from"./chunks/framework.DT-LCgF3.js";const e="/Li6Daily/assets/image.DPo5XbzN.png",c=JSON.parse('{"title":"UDP","description":"","frontmatter":{"date":"2025-12-19T09:23:47.000Z","title":"UDP","permalink":"/pages/0c6dab","categories":["Protocol","传输层协议"]},"headers":[],"relativePath":"Protocol/02.传输层协议/01.UDP.md","filePath":"Protocol/02.传输层协议/01.UDP.md","lastUpdated":1785924051000}'),l={name:"Protocol/02.传输层协议/01.UDP.md"};function o(d,t,p,i,P,h){return s(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="udp-协议简介" tabindex="-1">UDP 协议简介 <a class="header-anchor" href="#udp-协议简介" aria-label="Permalink to &quot;UDP 协议简介&quot;">​</a></h1><p>小刘，我们从工程视角来聊一聊 UDP（User Datagram Protocol），它在网络世界里是一个<strong>简单、直接、速度优先</strong>的角色。</p><p>UDP 位于 <strong>OSI 第四层（传输层）</strong>，与 TCP 同级，但设计哲学几乎相反： TCP 追求“可靠、完整、有序”，UDP 追求“快、轻、少约束”。</p><p><img src="'+e+`" alt="alt text" loading="lazy"></p><hr><h2 id="一、udp-是什么" tabindex="-1">一、UDP 是什么 <a class="header-anchor" href="#一、udp-是什么" aria-label="Permalink to &quot;一、UDP 是什么&quot;">​</a></h2><p>UDP 是一种<strong>无连接的传输层协议</strong>。 “无连接”不是说不能通信，而是通信前<strong>不建立连接、不维护状态</strong>。</p><p>换句话说，UDP 更像是“寄信”：</p><ul><li>写好内容</li><li>塞进信封</li><li>投递出去</li><li>至于对方是否收到、什么时候收到、顺序是否正确 —— 不关心</li></ul><hr><h2 id="二、udp-的核心特征" tabindex="-1">二、UDP 的核心特征 <a class="header-anchor" href="#二、udp-的核心特征" aria-label="Permalink to &quot;二、UDP 的核心特征&quot;">​</a></h2><h3 id="_1-无连接" tabindex="-1">1. 无连接 <a class="header-anchor" href="#_1-无连接" aria-label="Permalink to &quot;1. 无连接&quot;">​</a></h3><p>UDP 不需要三次握手，也没有连接建立和释放过程。只要知道对方 IP 和端口，就可以直接发送数据。 这意味着：启动快、延迟低、协议状态极少。</p><h3 id="_2-不保证可靠性" tabindex="-1">2. 不保证可靠性 <a class="header-anchor" href="#_2-不保证可靠性" aria-label="Permalink to &quot;2. 不保证可靠性&quot;">​</a></h3><p>UDP <strong>不保证</strong>：数据一定到达、只到达一次、按顺序到达。 协议本身不重传、不确认（ACK）、不做流量控制、不做拥塞控制。可靠性完全交给<strong>上层应用</strong>处理。</p><h3 id="_3-面向报文" tabindex="-1">3. 面向报文 <a class="header-anchor" href="#_3-面向报文" aria-label="Permalink to &quot;3. 面向报文&quot;">​</a></h3><p>UDP 是**面向报文（message-oriented）**的协议。发送端发一个 datagram，接收端要么完整收到、要么直接丢弃，<strong>不存在 TCP 那种「半包 / 粘包」语义</strong>。</p><h3 id="_4-协议头部极小" tabindex="-1">4. 协议头部极小 <a class="header-anchor" href="#_4-协议头部极小" aria-label="Permalink to &quot;4. 协议头部极小&quot;">​</a></h3><p>UDP 头部固定只有 <strong>8 字节</strong>（TCP 首部至少 20 字节），无连接状态、处理简单、传输效率高。</p><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>源端口（Source Port）</td><td>16 位</td><td>发送方端口号，<strong>可选</strong>。不需要对方回信时可填 0</td></tr><tr><td>目的端口（Destination Port）</td><td>16 位</td><td>接收方端口号，<strong>必填</strong></td></tr><tr><td>长度（Length）</td><td>16 位</td><td>UDP 数据报总长度（首部 8 + 数据），最小为 8</td></tr><tr><td>检验和（Checksum）</td><td>16 位</td><td><strong>可选</strong>（IPv4）；IPv6 下强制计算</td></tr></tbody></table><hr><h2 id="三、udp-报文格式" tabindex="-1">三、UDP 报文格式 <a class="header-anchor" href="#三、udp-报文格式" aria-label="Permalink to &quot;三、UDP 报文格式&quot;">​</a></h2><p>UDP 数据报由<strong>首部</strong>和<strong>数据</strong>组成，首部固定 8 字节：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|          源端口号            |          目的端口号            |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|            长度              |          检验和                |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                            数据 ...                          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>与 TCP 不同，UDP 首部<strong>没有「序号」「确认号」「窗口」「标志位」</strong>，因此非常简单。</p><hr><h2 id="四、校验和与伪首部" tabindex="-1">四、校验和与伪首部 <a class="header-anchor" href="#四、校验和与伪首部" aria-label="Permalink to &quot;四、校验和与伪首部&quot;">​</a></h2><p>UDP 的检验和采用与 TCP 相同的<strong>二进制反码求和</strong>算法。IPv4 下字段为 0 表示未计算；<strong>IPv6 下校验和强制必须计算</strong>。</p><p>计算时除了 UDP 首部和数据，还会拼上一个<strong>伪首部（Pseudo Header）</strong>。伪首部<strong>并不真实传输</strong>，仅用于校验，目的是让 UDP 能校验「数据报是否送到了正确的主机和协议」：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                      32 位源 IP 地址                         |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                     32 位目的 IP 地址                       |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>| 保留(0) | 协议(17) |            UDP 长度                     |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li>协议号 <strong>17</strong> 表示 UDP（TCP 为 6），用于确认上层协议身份。</li><li>接收方校验和出错时，UDP 直接<strong>丢弃该数据报</strong>，不发送任何差错通知（再次体现「不可靠」）。</li><li>发送方未计算校验和（字段为 0）时，接收方<strong>不会</strong>因字段为 0 而丢弃，而是跳过校验。</li></ul><hr><h2 id="五、udp-为什么是不可靠的" tabindex="-1">五、UDP 为什么是不可靠的 <a class="header-anchor" href="#五、udp-为什么是不可靠的" aria-label="Permalink to &quot;五、UDP 为什么是不可靠的&quot;">​</a></h2><p>UDP 之所以「不可靠」，是因为它在协议层面<strong>刻意不做</strong>以下事情：</p><ul><li><strong>无确认机制</strong>：发出后不等待确认，也无从得知对方是否收到。</li><li><strong>无重传机制</strong>：丢失、重复、乱序时不重发、不纠正。</li><li><strong>无流量控制</strong>：不考虑接收方缓冲区是否溢出。</li><li><strong>无拥塞控制</strong>：网络拥塞时仍按原速率发送，可能雪上加霜。</li></ul><p>这些「缺失」并非缺陷，而是<strong>设计取舍</strong>：换来了极低的首部开销和最低延迟。可靠性如果需要，就由<strong>应用层协议</strong>自己实现。</p><hr><h2 id="六、优势与劣势" tabindex="-1">六、优势与劣势 <a class="header-anchor" href="#六、优势与劣势" aria-label="Permalink to &quot;六、优势与劣势&quot;">​</a></h2><p><strong>优势</strong>（从系统/性能角度）：</p><ol><li><strong>低延迟</strong>：无连接、无确认、无重传等待。</li><li><strong>低开销</strong>：协议头小、状态管理少、内核负担轻。</li><li><strong>可控性强</strong>：应用层可自定义重传、顺序、拥塞控制、加密与校验。</li></ol><p><strong>劣势</strong>：</p><ul><li>丢包、乱序、重复包是常态。</li><li>网络拥塞时不「自我约束」。</li><li>因此<strong>不适合</strong>：文件传输（直接用）、强一致性数据同步、对可靠性极端敏感的场景。</li></ul><hr><h2 id="七、适用场景与典型应用协议" tabindex="-1">七、适用场景与典型应用协议 <a class="header-anchor" href="#七、适用场景与典型应用协议" aria-label="Permalink to &quot;七、适用场景与典型应用协议&quot;">​</a></h2><p>UDP 特别适合「<strong>可以容忍少量丢失，但不能接受高延迟</strong>」的场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>实时音视频（直播、通话、会议）</td><td>容忍少量丢包，但无法容忍重传带来的几百毫秒延迟</td></tr><tr><td>实时游戏 / 多人竞技</td><td>延迟敏感，丢包比卡顿更可接受</td></tr><tr><td>广播 / 组播</td><td>TCP 是点对点连接，UDP 天然支持一对多</td></tr><tr><td>海量小请求（DNS、DHCP 查询）</td><td>一次请求一次响应，建连开销不划算</td></tr><tr><td>高速内网传输（TFTP、数据库同步）</td><td>链路质量好，可靠性由应用保证更高效</td></tr><tr><td>需要自定义可靠性的场景</td><td>应用层可实现比 TCP 更贴合业务的可靠机制（QUIC、KCP）</td></tr></tbody></table><p>基于 UDP 的典型应用协议：</p><ul><li><strong>DNS</strong>：通常基于 UDP 53，一次查询一次响应，超时后才可能走 TCP。</li><li><strong>DHCP</strong>：客户端初始没有 IP，无法建 TCP 连接，只能用广播 UDP。</li><li><strong>TFTP / SNMP / RIP / RTP·RTCP</strong>：轻量文件传输、网管、路由、音视频流媒体载体。</li><li><strong>QUIC（HTTP/3 的底层）</strong>：在 UDP 之上实现可靠、有序、0-RTT、拥塞控制。</li></ul><hr><h2 id="八、udp-上如何实现「可靠传输」" tabindex="-1">八、UDP 上如何实现「可靠传输」 <a class="header-anchor" href="#八、udp-上如何实现「可靠传输」" aria-label="Permalink to &quot;八、UDP 上如何实现「可靠传输」&quot;">​</a></h2><p>当应用确实需要可靠，又想保留 UDP 的低延迟/灵活性时，常见做法是在<strong>应用层自己做可靠性</strong>：</p><ul><li><strong>QUIC（HTTP/3）</strong>：Google 提出，现为标准。在 UDP 之上实现可靠有序、0-RTT/1-RTT 建连、多路复用且无队头阻塞、连接迁移。</li><li><strong>KCP</strong>：以牺牲带宽换低延迟的可靠 UDP 方案，广泛用于游戏、弱网传输。</li><li><strong>WebRTC / SRTP</strong>：媒体数据走 UDP（RTP/SRTP），丢包时通过前向纠错（FEC）、丢帧而非重传来保证流畅。</li><li><strong>自研可靠 UDP</strong>：游戏、IM 常基于 UDP 自研序号、确认、超时重传、拥塞控制的子集，做到「刚好可靠」。</li></ul><hr><h2 id="九、udp-与-tcp-对比" tabindex="-1">九、UDP 与 TCP 对比 <a class="header-anchor" href="#九、udp-与-tcp-对比" aria-label="Permalink to &quot;九、UDP 与 TCP 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接性</td><td>面向连接（三次握手、四次挥手）</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠（确认、重传、序号）</td><td>不可靠（尽最大努力交付）</td></tr><tr><td>顺序性</td><td>保证按序到达</td><td>不保证顺序</td></tr><tr><td>数据边界</td><td>字节流，无消息边界（可能粘包/拆包）</td><td>保留报文边界（面向报文）</td></tr><tr><td>速度</td><td>较慢（握手、确认、控制开销）</td><td>较快</td></tr><tr><td>首部开销</td><td>20~60 字节</td><td>8 字节</td></tr><tr><td>流量控制</td><td>有（滑动窗口）</td><td>无</td></tr><tr><td>拥塞控制</td><td>有（慢启动、拥塞避免等）</td><td>无</td></tr><tr><td>通信模式</td><td>仅一对一</td><td>一对一、一对多、多对多、广播/组播</td></tr><tr><td>适用场景</td><td>文件传输、网页、邮件</td><td>音视频、DNS、游戏、实时通信</td></tr></tbody></table><hr><h2 id="十、常见问题" tabindex="-1">十、常见问题 <a class="header-anchor" href="#十、常见问题" aria-label="Permalink to &quot;十、常见问题&quot;">​</a></h2><p><strong>Q1：UDP 会粘包/拆包吗？</strong> 不会。UDP 是「面向报文」的，保留应用层交付的报文边界：一次 <code>sendto</code> 对应一次 <code>recvfrom</code>，不会合并也不会拆分。所谓「UDP 粘包」通常是应用层把多个逻辑消息塞进了一个数据报。</p><p><strong>Q2：UDP 最大能发多大？</strong> 长度字段 16 位，最大 65535 字节，减 8 字节首部，单包数据最大 <strong>65527 字节</strong>。但受 <strong>MTU</strong>（以太网通常 1500）限制，超过会在 IP 层分片，任一片丢失整包作废，因此<strong>实际建议控制在 1472 字节（1500 - 20 IP - 8 UDP）以内</strong>避免分片。</p><p><strong>Q3：UDP 不是不可靠吗，为什么 DNS 用 UDP？</strong> DNS 查询通常一次请求一次响应，数据量小、对延迟敏感；用 TCP 多一次握手往返代价过高。DNS 在响应超时会改用 TCP，重要区传输（AXFR）本就走 TCP——「默认 UDP 追求快，必要时退化到 TCP 保证可靠」。</p><p><strong>Q4：如何对 UDP 做「限流/防拥塞」？</strong> UDP 自身没有拥塞控制，大量使用（自研可靠 UDP、QUIC、视频推流）需在<strong>应用层</strong>实现拥塞控制（如 QUIC 自带 BBR-like 算法、KCP 流控），否则容易把网络打满。</p><hr><h2 id="十一、工程实践中的一句话总结" tabindex="-1">十一、工程实践中的一句话总结 <a class="header-anchor" href="#十一、工程实践中的一句话总结" aria-label="Permalink to &quot;十一、工程实践中的一句话总结&quot;">​</a></h2><p>小刘，如果用一句工程化的话来总结 UDP：</p><blockquote><p>UDP 提供的是“传输能力”，而不是“传输保证”。</p></blockquote><p>是否可靠、是否有序、是否安全，完全取决于你在应用层愿意付出多少设计成本。当你追求极致性能、低延迟、强可控性时，UDP 往往是那个值得认真对待的底座协议。</p>`,66)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
